Map<String, Integer> m = new ConcurrentHashMap<>();
// writers are hammering m from other threads
int n = m.size();

Map<String, Integer> m = new ConcurrentHashMap<>();
m.putIfAbsent("a", 1);
m.putIfAbsent("a", 2);
m.merge("a", 10, Integer::sum);
System.out.println(m.get("a"));

